import{_ as a,o as r,c as s,a5 as o}from"./chunks/framework.PLGyiLjE.js";const d=JSON.parse('{"title":"Combat basics","description":"","frontmatter":{},"headers":[],"relativePath":"guides/combat.md","filePath":"guides/combat.md"}'),n={name:"guides/combat.md"};function e(i,t,l,g,h,u){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="combat-basics" tabindex="-1">Combat basics <a class="header-anchor" href="#combat-basics" aria-label="Permalink to &quot;Combat basics&quot;">​</a></h1><h2 id="your-string" tabindex="-1">Your string <a class="header-anchor" href="#your-string" aria-label="Permalink to &quot;Your string&quot;">​</a></h2><ul><li><strong>Attack ×3:</strong> the third hit is the <strong>Launcher</strong> and throws a foe up.</li><li><strong>Attack, Attack, pause, Attack:</strong> a <strong>Heavy Blow</strong> that knocks foes flat.</li><li><strong>Up + Attack:</strong> <strong>Rising Strike</strong> · <strong>Down + Attack:</strong> <strong>Sweep</strong></li><li><strong>Dash, then Attack:</strong> <strong>Lunge</strong> · <strong>Jump, then Down + Attack:</strong> <strong>Air Slam</strong></li><li>Launch a foe, jump and hit it in the air: <strong>Air Catch</strong>.</li><li>Knock a foe into a wall, hit it as it bounces back: <strong>Wall Bounce</strong>.</li></ul><h2 id="jump-and-dash" tabindex="-1">Jump and dash <a class="header-anchor" href="#jump-and-dash" aria-label="Permalink to &quot;Jump and dash&quot;">​</a></h2><ul><li>Press Jump again in the air to <strong>double jump</strong>.</li><li><strong>Perfect Dodge:</strong> Dash through a swing, then Attack to counter.</li><li>Creatures hurt when you walk into them. Jump over or dash through.</li></ul><h2 id="guard-and-parry" tabindex="-1">Guard and parry <a class="header-anchor" href="#guard-and-parry" aria-label="Permalink to &quot;Guard and parry&quot;">​</a></h2><ul><li>Guard: <strong>Z</strong> with nothing to use (<strong>G</strong> on WASD, <strong>Tap Guard</strong> on touch).</li><li><strong>Parry:</strong> guard as a swing lands, then Attack. The foe reels.</li><li><strong>Counter:</strong> hit a foe as it winds up. <strong>Punish:</strong> hit it as it recovers from a miss.</li><li>Shields block hits. Use your third hit, a skill, or strike from behind.</li></ul><h2 id="tatterlight" tabindex="-1">Tatterlight <a class="header-anchor" href="#tatterlight" aria-label="Permalink to &quot;Tatterlight&quot;">​</a></h2><p>Landing hits fills your <strong>Tatterlight</strong> meter, faster up close. It drains when you stop fighting and is split into four <strong>scraps</strong>.</p><ul><li><strong>Tatterburst:</strong> Tatterlight full, <strong>Dash + Attack</strong> knocks every foe on screen flat.</li><li><strong>Tie Off:</strong> press Dash while a move is finishing. Spends one scrap. (Not when Tatterlight is full: Dash is kept for the Tatterburst.)</li></ul><h2 id="skill-links" tabindex="-1">Skill links <a class="header-anchor" href="#skill-links" aria-label="Permalink to &quot;Skill links&quot;">​</a></h2><p>After two Attacks on the ground, a ready skill gets a gold <strong>LINK</strong> badge. Use it then for a stronger hit that keeps your string going.</p><p><strong>Relays</strong> (party) A teammate launches a foe, you hit it in the air: <strong>Relay!</strong> Extra damage and score.</p><h2 id="practice" tabindex="-1">Practice <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;Practice&quot;">​</a></h2><ul><li><strong>Combo list</strong> in the Pause menu shows the moves and skill links for your class.</li><li><strong>Drills</strong> in Loomhaven are short practice runs with nothing to lose: <strong>Launch, catch, slam</strong>, <strong>Parry a charger</strong>, <strong>Tie Off</strong>, <strong>Tatterburst</strong> and a <strong>Damage test</strong>.</li></ul>',15)])])}const m=a(n,[["render",e]]);export{d as __pageData,m as default};
